const THEME_KEY='prepone_theme';
function currentTheme(){const saved=localStorage.getItem(THEME_KEY);return saved==='light'||saved==='dark'?saved:'dark'}
function refreshThemeButtons(){const light=document.documentElement.dataset.theme==='light';qs('[data-theme-toggle]').forEach(b=>{const icon=b.querySelector('.themeGlyph'),txt=b.querySelector('.themeText');if(icon)icon.textContent=light?'☾':'☀';if(txt)txt.textContent=light?'Dark':'Light';b.setAttribute('aria-label',light?'Switch to dark mode':'Switch to light mode');b.title=light?'Switch to dark mode':'Switch to light mode'})}
function applyTheme(theme,persist=false){const t=theme==='light'?'light':'dark';document.documentElement.dataset.theme=t;if(persist)localStorage.setItem(THEME_KEY,t);refreshThemeButtons()}
