const param=k=>new URLSearchParams(location.search).get(k)||'';
function normalizeUrl(v){let u=String(v||'').trim();if(/^http:\/\/script\.google\.com\//i.test(u))u='https://'+u.slice(7);return u}
function apiReady(){return /^https:\/\/script\.google\.com\/macros\/s\/[^/]+\/exec(?:$|\?)/.test(C.API_URL||'')}
function studentToken(){return localStorage.getItem('prepone_student_token')||''}
function studentName(){return localStorage.getItem('prepone_student_name')||''}
function studentId(){return localStorage.getItem('prepone_student_id')||''}
function saveStudentSession(d){localStorage.setItem('prepone_student_token',d.token||'');localStorage.setItem('prepone_student_name',d.student?.StudentName||'');localStorage.setItem('prepone_student_id',d.student?.StudentID||'')}
function clearStudentSession(){['prepone_student_token','prepone_student_name','prepone_student_id'].forEach(k=>localStorage.removeItem(k))}
function teacherToken(){return sessionStorage.getItem('prepone_teacher_token')||''}
function setTeacherToken(t){t?sessionStorage.setItem('prepone_teacher_token',t):sessionStorage.removeItem('prepone_teacher_token')}
function apiUrl(action,params={}){const u=new URL(C.API_URL);u.searchParams.set('action',action);u.searchParams.set('t',Date.now());Object.entries(params||{}).forEach(([k,v])=>u.searchParams.set(k,String(v??'')));return u.toString()}
function rawJsonp(action,params={}){return new Promise((resolve,reject)=>{if(!apiReady())return reject(Error('Live Sheet backend is not configured.'));const cb='prep_'+Date.now()+'_'+Math.random().toString(36).slice(2),s=document.createElement('script');let finished=false;const done=(err,data)=>{if(finished)return;finished=true;clearTimeout(timer);try{delete window[cb]}catch(_){}s.remove();err?reject(err):resolve(data)};const timer=setTimeout(()=>done(Error('Backend response timed out. Please retry.')),20000);window[cb]=d=>done(null,d);s.onerror=()=>done(Error('Backend unavailable. Check the /exec URL and deployment access.'));const u=new URL(apiUrl(action,{...params,callback:cb}));s.src=u.toString();document.head.appendChild(s)})}
const MUTATING_ACTIONS=new Set(['studentlogin','resourceprogress','studentsavenote','studentdeletenote','teachersetup','teachersavestudent','teacherdeletestudent']);
let BACKEND_IDENTITY_PROMISE=null;
function backendSheetId(d){return String(d?.actualSpreadsheetId||d?.masterSpreadsheetId||d?.spreadsheetId||d?.readSpreadsheetId||'').trim()}
function isUnknownActionResponse(d){return !!d&&d.ok===false&&/unknown\s*action/i.test(String(d.error||''))}
function verifiedIdentity_(d,source){
  if(!d||d.ok===false)throw Error(d?.error||'Backend identity check failed');
  const expected=String(C.MASTER_SPREADSHEET_ID||'').trim();
  const actual=backendSheetId(d);
  if(!actual)throw Error('Backend did not report its Google Sheet ID. Course loading is blocked to prevent old-sheet access.');
  if(expected&&actual!==expected)throw Error('Wrong Apps Script deployment: it is connected to a different Google Sheet. Access is blocked.');
  return {...d,actualSpreadsheetId:actual,masterSpreadsheetId:actual,identitySource:source,writeSpreadsheetId:String(d.writeSpreadsheetId||actual).trim(),readSpreadsheetId:String(d.readSpreadsheetId||actual).trim(),writeTargetVerified:d.writeTargetVerified===false?false:true,readWriteUnified:d.readWriteUnified===false?false:true};
}
async function fetchBackendIdentity_(){
  // V14+ exposes storageidentity. Earlier unified backends expose the same Sheet ID through health.
  // Supporting health here keeps course content available while still STRICTLY rejecting any old Sheet ID.
  try{
    const d=await rawJsonp('storageidentity');
    if(d&&!isUnknownActionResponse(d))return verifiedIdentity_(d,'storageidentity');
  }catch(e){
    // Fall through to health only; health must still prove the exact configured master Sheet.
  }
  const h=await rawJsonp('health');
  return verifiedIdentity_(h,'health');
}
async function backendIdentity(force=false){
  if(force)BACKEND_IDENTITY_PROMISE=null;
  if(!BACKEND_IDENTITY_PROMISE)BACKEND_IDENTITY_PROMISE=fetchBackendIdentity_().catch(e=>{BACKEND_IDENTITY_PROMISE=null;throw e});
  return BACKEND_IDENTITY_PROMISE;
}
async function jsonp(action,params={}){
  const name=String(action||'').toLowerCase();
  if(name==='health'||name==='storageidentity')return rawJsonp(action,params);
  const expected=String(C.MASTER_SPREADSHEET_ID||'').trim();
  // Writes are still pre-verified immediately before mutation.
  if(MUTATING_ACTIONS.has(name)){
    const identity=await backendIdentity(true);
    if(expected&&backendSheetId(identity)!==expected)throw Error('Request blocked: backend is not connected to the configured master Sheet.');
  }
  // Reads use the response's backend metadata as their strict proof. This removes an extra
  // Apps Script round-trip and makes public course loading substantially faster.
  const d=await rawJsonp(action,params);
  const responseSheet=backendSheetId(d);
  if(expected&&!responseSheet)throw Error('Backend did not report its Google Sheet ID. Response blocked.');
  if(expected&&responseSheet!==expected)throw Error('Wrong Apps Script deployment: response came from a different Google Sheet.');
  return d;
}
async function sha256(text){const b=new TextEncoder().encode(String(text));const h=await crypto.subtle.digest('SHA-256',b);return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function uiEnabled(v){const s=String(v??'').trim().toLowerCase();return !['false','0','no','off','inactive'].includes(s)}
