function examIconHtml(e,extra=''){const logo=normalizeUrl(e?.LogoURL||e?.logoUrl||'');const fallback=iconFor(e?.ExamID||'');const cls=['examIcon',extra,logo?'examLogo':''].filter(Boolean).join(' ');return logo?`<span class="${cls}"><span class="examIconFallback">${fallback}</span><img src="${esc(logo)}" alt="${esc((e?.ShortName||e?.ExamName||e?.ExamID||'Exam')+' logo')}" loading="lazy" referrerpolicy="no-referrer"></span>`:`<span class="${cls}">${fallback}</span>`}
