function officialBtn(e,cls='btn ghost'){const u=normalizeUrl(e?.OfficialURL);return u?`<a class="${cls} officialBtn" target="_blank" rel="noopener noreferrer" href="${esc(u)}">Official Website ↗</a>`:''}
function setBackendBadge(mode='live'){const el=$('backendBadge');if(!el)return;if(!apiReady()){el.textContent='● Course Data';el.style.color='#a5b4fc';el.title='Course content available';return}el.textContent='● Live Sheet';el.style.color='#6ee7b7';el.title='Connected to course data'}
function nav(){const sn=studentName();return `<header class="topbar"><div class="shell topin"><a class="brand brandFull brandFullWithName" href="index.html" aria-label="PrepOne — ITR Computer and Skill Center"><span class="brandLogoFrame"><img class="brandFullLogo" src="assets/itr-logo.png?v=14.3.7" alt="ITR Computer and Skill Center"></span><span class="brandDivider" aria-hidden="true"></span><span class="brandCopy"><b>PrepOne</b><small>SELF PREPARATION STUDIO</small></span></a><nav class="nav"><a href="index.html#courses">Courses</a>${sn?`<a href="student.html">${esc(sn)}</a><button onclick="logoutStudent()">Logout</button>`:`<a href="index.html#studentAccess" onclick="if(document.getElementById('studentAccess')){openStudentLogin();return false}">Student Login</a>`}<a href="teacher.html">Teacher</a>${themeButton()}<span id="backendBadge" class="chip">●</span></nav><div class="mobileTopActions">${themeButton('mobileTheme')}<button class="btn mobileMenu" onclick="location.href='index.html'">Courses</button></div></div></header>`}
