const EXAM_UPDATE_STORE=new Map();
function formatUpdateDate(v){if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return'';return d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}
function examUpdateStrip(examId,items=[]){
  const list=(items||[]).filter(Boolean);
  if(!list.length){const title='Latest '+String(examId||'exam').replace(/_/g,' ')+' updates';const u={ExamID:examId,Title:title,Summary:'Latest official exam information is available from the exam authority.',Content:'Open the official exam source for the newest published information.',PublishedAt:new Date().toISOString(),SourceName:'Official update',URL:'',Kind:'official-latest'};EXAM_UPDATE_STORE.set(`${examId}:0`,u);return `<div class="examUpdates newsTicker" data-news-ticker data-count="1"><div class="updateHead"><span class="updatePulse"></span><b>Recent update</b></div><div class="tickerViewport"><button class="updateItem tickerItem active" data-ticker-index="0" data-update-key="${esc(examId+':0')}" aria-hidden="false"><span class="updateDate">${esc(formatUpdateDate(u.PublishedAt))}</span><span class="tickerText"><b>${esc(u.Title)}</b><small>Official update • Click for full update</small></span><span class="tickerArrow">↗</span></button></div></div>`;}
  list.forEach((u,i)=>EXAM_UPDATE_STORE.set(`${examId}:${i}`,u));
  return `<div class="examUpdates newsTicker" data-news-ticker data-count="${list.length}"><div class="updateHead"><span class="updatePulse"></span><b>Recent update</b>${list.length>1?`<span class="tickerCount">1/${list.length}</span>`:''}</div><div class="tickerViewport">${list.map((u,i)=>`<button class="updateItem tickerItem ${i===0?'active':''}" data-ticker-index="${i}" data-update-key="${esc(examId+':'+i)}" aria-hidden="${i===0?'false':'true'}"><span class="updateDate">${esc(formatUpdateDate(u.PublishedAt))}</span><span class="tickerText"><b>${esc(u.Title)}</b><small>${esc(u.SourceName||'Update')} • Click for full update</small></span><span class="tickerArrow">↗</span></button>`).join('')}</div></div>`
}
