function wireExamUpdates(root=document){
  const scope=root&&root.querySelectorAll?root:document;
  [...scope.querySelectorAll('.updateItem')].forEach(b=>b.onclick=()=>openExamUpdate(b.dataset.updateKey));
  [...scope.querySelectorAll('[data-news-ticker]')].forEach(ticker=>{
    if(ticker.dataset.tickerWired==='1')return;
    ticker.dataset.tickerWired='1';
    const items=[...ticker.querySelectorAll('.tickerItem')];
    if(items.length<2)return;
    let index=0,timer=null;
    const count=ticker.querySelector('.tickerCount');
    const show=next=>{
      const previous=items[index];
      index=(next+items.length)%items.length;
      const current=items[index];
      if(previous===current)return;
      previous.classList.remove('active');previous.setAttribute('aria-hidden','true');
      current.classList.remove('tickerEnter');void current.offsetWidth;current.classList.add('active','tickerEnter');current.setAttribute('aria-hidden','false');
      if(count)count.textContent=`${index+1}/${items.length}`;
    };
    const start=()=>{if(timer)return;timer=setInterval(()=>show(index+1),4200)};
    const stop=()=>{if(timer){clearInterval(timer);timer=null}};
    ticker.addEventListener('mouseenter',stop);ticker.addEventListener('mouseleave',start);
    ticker.addEventListener('focusin',stop);ticker.addEventListener('focusout',start);
    if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)start();
  });
}
