async function initStudentAccess(){
  const search=$('studentSearch'), select=$('studentSelect'), pass=$('studentPassword'), btn=$('studentLoginBtn'), msg=$('studentLoginMsg'), hint=$('studentPickerMsg');
  if(!select||!btn)return;
  if(select.dataset.loaded==='1')return;
  let students=[];
  const renderStudents=(query='')=>{
    const q=String(query||'').trim().toLowerCase();
    const filtered=students.filter(s=>!q||String(s.StudentName||'').toLowerCase().includes(q));
    select.innerHTML=filtered.length
      ? `<option value="">Select your name</option>`+filtered.map(s=>`<option value="${esc(s.StudentID)}">${esc(s.StudentName)}</option>`).join('')
      : '<option value="">No matching student found</option>';
    if(hint){hint.textContent=students.length?'':'No active students available.';hint.classList.toggle('hidden',!!students.length)}
  };
  if(!apiReady()){
    msg.textContent='Live Sheet backend is not configured.';
    if(hint)hint.textContent='Connect the live Apps Script backend to load student names.';
    select.innerHTML='<option value="">Backend not connected</option>';
    return;
  }
  try{
    const d=await jsonp('studentsPublic');
    students=(d.students||[]).filter(s=>s.StudentID&&s.StudentName);
    students.sort((a,b)=>String(a.StudentName).localeCompare(String(b.StudentName)));
    select.dataset.loaded='1';renderStudents();
  }catch(e){
    select.innerHTML='<option value="">Could not load students</option>';
    if(hint)hint.textContent='Student list could not be loaded. Please try again or contact your teacher.';
    msg.textContent=e.message||'Could not load students.';
    return;
  }
  search.oninput=()=>renderStudents(search.value);
  search.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();select.focus()}};
  select.onchange=()=>{if(select.value)msg.textContent=''};
  btn.onclick=async()=>{
    const id=select.value,pw=pass.value;
    if(!id){msg.textContent='Select your name first.';select.focus();return}
    if(!pw){msg.textContent='Enter your password.';pass.focus();return}
    btn.disabled=true;msg.textContent='Signing in…';
    try{
      const hash=await sha256(pw),d=await jsonp('studentLogin',{studentId:id,passwordHash:hash});
      if(!d.ok)throw Error(d.error||'Login failed');
      saveStudentSession(d);location.href='student.html';
    }catch(e){msg.textContent=e.message||'Login failed'}finally{btn.disabled=false}
  };
}
