async function initStudy(){document.body.insertAdjacentHTML('afterbegin',nav());document.body.insertAdjacentHTML('beforeend',footer());refreshThemeButtons();setBackendBadge();const id=param('exam')||'AP_EAPCET_E',initialSubject=param('subject')||'';const status=$('contentStatus');try{const d=await loadExamData(id),e=d.exam;if(!e)throw Error('Exam not found.');$('heroSlot').innerHTML=examHeader(e);const allRows=d.syllabus||[],subjects=uniqueVals(allRows,'Subject'),ctx=await getStudentContext(id),track=!!ctx,pmap=progressIndex(ctx?.progress||[]),notes=track?await loadStudentNotes():[];if($('studentCourseBar'))$('studentCourseBar').innerHTML=track?`<div class="studentCourseBar glass"><span>Tracking for <b>${esc(ctx.student.StudentName)}</b></span><a href="student.html">My Learning →</a></div>`:'';if(status){const sourceLabel='live Sheet';status.className='contentStatus ok';status.textContent=`Content loaded from ${sourceLabel} • ${allRows.length} topics • ${subjects.length} subjects${track?' • progress tracking on':''}`}if(!subjects.length){$('sideLinks').innerHTML='';$('studyTitle').textContent='No syllabus found';$('chapters').innerHTML='<div class="empty">The Sheet has no active syllabus rows for this exam.</div>';return}const search=$('courseSearch'),subjectSel=$('subjectFilter'),chapterSel=$('chapterFilter'),summary=$('filterSummary');let state={subject:subjects.includes(initialSubject)?initialSubject:'',chapter:'',query:''};setSelectOptions(subjectSel,subjects,'All Subjects',state.subject);const chapterChoices=()=>uniqueVals(allRows.filter(r=>!state.subject||r.Subject===state.subject),'Chapter');const syncChapters=()=>{if(state.chapter&&!chapterChoices().includes(state.chapter))state.chapter='';setSelectOptions(chapterSel,chapterChoices(),'All Chapters',state.chapter)};syncChapters();function renderSide(){$('sideLinks').innerHTML=`<button class="sideLink ${!state.subject?'active':''}" data-subject=""><span>All Subjects</span><span>${allRows.length}</span></button>`+subjects.map(s=>`<button class="sideLink ${s===state.subject?'active':''}" data-subject="${esc(s)}"><span>${esc(s)}</span><span>${allRows.filter(x=>x.Subject===s).length}</span></button>`).join('');qs('#sideLinks .sideLink').forEach(b=>b.onclick=()=>{state.subject=b.dataset.subject||'';state.chapter='';subjectSel.value=state.subject;syncChapters();render()})}function render(){renderSide();const rows=allRows.filter(r=>(!state.subject||r.Subject===state.subject)&&(!state.chapter||r.Chapter===state.chapter)&&courseRowMatches(r,state.query));$('studyTitle').textContent=state.subject||(state.query?'Search results':'All Subjects');if(summary)summary.innerHTML=`<b>${rows.length}</b> topic${rows.length===1?'':'s'} shown`;if(!rows.length){$('chapters').innerHTML='<div class="empty searchEmpty"><b>No matching topics</b><span>Try a broader search or reset the filters.</span></div>';return}let key=0,chapterKey=0;$('chapters').innerHTML=uniqueVals(rows,'Subject').map(sub=>{const sr=rows.filter(r=>r.Subject===sub);return `<section class="subjectBlock"><div class="subjectRibbon"><span>SUBJECT</span><b>${esc(sub)}</b><em>${sr.length} topics</em></div>${uniqueVals(sr,'Chapter').map(ch=>{const cr=sr.filter(r=>r.Chapter===ch),cid=`chapter-body-${chapterKey++}`;return `<div class="chapter"><button type="button" class="chapterHead chapterToggle" data-chapter-body="${cid}" aria-expanded="true"><div class="chapterIdentity"><span class="chapterBadge">CHAPTER</span><b>${esc(ch)}</b></div><span class="chapterHeadRight"><span>${cr.length} topics</span><b class="chapterChevron">−</b></span></button><div id="${cid}" class="chapterBody">${cr.map(t=>{const k=key++,resources=topicResourceLinks(t),c=completionForTopic(t,pmap);return `<div class="topicItem ${resources.length?'hasResources':'emptyTopic'} ${track&&c.complete?'topicDone':''}"><button class="topicLaunch ${resources.length?'':'noResources'}" ${resources.length?`data-topic-panel="topic-${k}"`:''}><span class="topicMain"><span class="topicBadge">TOPIC</span><span class="topicTitle">${esc(t.Topic)}</span>${resources.length?`<span class="topicMeta">${track?`${c.done}/${c.total} completed`:`${resources.length} learning item${resources.length===1?'':'s'}`}</span>`:''}</span>${resources.length?`<span class="topicOpenCue">${track&&c.complete?'✓ Complete':'Open topic'} <b>→</b></span>`:''}</button>${topicWorkspace(t,resources,k,pmap,track,notes)}</div>`}).join('')}</div></div>`}).join('')}</section>`}).join('');wireChapterCollapse();wireTopicWorkspace(track,notes)}search.oninput=()=>{state.query=search.value.trim();render()};$('clearCourseSearch').onclick=()=>{search.value='';state.query='';render();search.focus()};subjectSel.onchange=()=>{state.subject=subjectSel.value;state.chapter='';syncChapters();render()};chapterSel.onchange=()=>{state.chapter=chapterSel.value;render()};$('resetCourseFilters').onclick=()=>{state={subject:'',chapter:'',query:''};search.value='';subjectSel.value='';syncChapters();render()};render()}catch(e){if(status){status.className='contentStatus warn';status.textContent='Unable to load live Sheet content.'}$('studyTitle').textContent='Content unavailable';$('chapters').innerHTML=`<div class="errorCard glass"><b>Could not fetch this course</b><span>${esc(e.message)}</span><div class="heroActions"><button class="btn primary" onclick="location.reload()">Retry</button><a class="btn" href="diagnostics.html">Open Diagnostics</a></div><small>Make sure the Apps Script is deployed as a Web App and the live Master Sheet ID is configured.</small></div>`}}
function examCountdownHtml(c){
  const label=String(c?.CountdownLabel||'').trim(),date=String(c?.ExamDateLabel||'').trim(),status=String(c?.ResolvedDateStatus||'').trim(),source=normalizeUrl(c?.ResolvedDateSource||'');
  if(!label&&!date)return '';
  const state=String(c?.CountdownState||'unknown');
  return `<div class="examCountdown ${esc(state)}"><div class="countdownMain"><span>${esc(label||'Exam date')}</span><b>${esc(date||'Date not available')}</b></div><div class="countdownMeta"><small>${esc(status||'Schedule')}</small>${source?`<a href="${esc(source)}" target="_blank" rel="noopener noreferrer">Date source ↗</a>`:''}</div></div>`;
}
async function initStudentDashboard(){document.body.insertAdjacentHTML('afterbegin',nav());document.body.insertAdjacentHTML('beforeend',footer());refreshThemeButtons();setBackendBadge();const root=$('studentDashboard'),token=studentToken();if(!token){root.innerHTML=loginRequiredCard();return}try{const d=await jsonp('studentDashboard',{token});if(!d.ok)throw Error(d.error||'Could not load dashboard');saveStudentSession({token,student:d.student});const t=d.totals||{},courses=d.courses||[],recent=d.recent||[];root.innerHTML=`<section class="studentHero glass"><div><div class="eyebrow">Student dashboard</div><h1>Welcome, ${esc(d.student.StudentName)}</h1></div><button class="btn" onclick="logoutStudent()">Logout</button></section><section class="studentKpis"><div class="stat"><span>Assigned courses</span><b>${courses.length}</b></div><div class="stat"><span>Resources complete</span><b>${t.completed||0}/${t.resources||0}</b></div><div class="stat"><span>Topics complete</span><b>${t.topicsDone||0}/${t.topics||0}</b></div><div class="stat"><span>Overall progress</span><b>${t.percent||0}%</b></div></section>${courses.length?`<section class="section studentCoursesSection"><div class="sectionHead"><div><div class="eyebrow">Assigned to me</div><h2>My courses</h2></div><a class="btn" href="index.html#courses">Browse public courses</a></div><div class="studentCourseGrid">${courses.map(c=>`<article class="studentCourseCard glass" style="--glow:${glowFor(c.ExamID)}"><div class="courseTop">${examIconHtml(c,'small')}<span>${c.percent}%</span></div><h3>${esc(c.ExamName)}</h3><p>${c.completedResources}/${c.totalResources} resources • ${c.completedTopics}/${c.totalTopics} topics</p>${examCountdownHtml(c)}<div class="progressBar"><div class="progressFill" style="width:${c.percent}%"></div></div><div class="studentCourseActions"><a class="btn primary" href="study.html?exam=${encodeURIComponent(c.ExamID)}">Open Course</a>${officialBtn(c,'btn ghost')}</div></article>`).join('')}</div></section>`:`<section class="contentCard glass emptyStateCard"><div class="eyebrow">No course assigned</div><h2>Your teacher has not assigned a course yet.</h2><p>Ask your teacher to assign an exam from the Teacher dashboard. Your dashboard will update automatically after assignment.</p><a class="btn" href="index.html#courses">Browse public courses</a></section>`}${recent.length?`<section class="contentCard glass recentCard"><div class="sectionHead"><div><div class="eyebrow">Recent activity</div><h2>Continue learning</h2></div></div><div class="recentList">${recent.slice(0,6).map(r=>`<a href="study.html?exam=${encodeURIComponent(r.ExamID)}&subject=${encodeURIComponent(r.Subject)}"><b>${esc(r.Topic)}</b><span>${esc(r.ResourceLabel)} • ${esc(r.Subject)}</span></a>`).join('')}</div></section>`:''}`}catch(e){clearStudentSession();root.innerHTML=loginRequiredCard(e.message)}}
function teacherLoginCard(){return `<section class="authCard glass"><div class="eyebrow">Teacher access</div><h2>Student Access Manager</h2><p>Manage student accounts, passwords and assigned courses. Teacher access is read from <b>Settings → TeacherPassword</b> in the master Sheet.</p><input id="teacherPassword" class="field" type="password" placeholder="Teacher password" autocomplete="current-password"><button id="teacherLoginBtn" class="btn primary">Sign in</button><div id="teacherMsg" class="formMsg"></div></section>`}
function teacherSetupCard(){return `<section class="authCard glass"><div class="eyebrow">Teacher password</div><h2>Set it in the master Sheet</h2><p>Open the <b>Settings</b> tab and enter your password in the <b>TeacherPassword</b> row under the Value column. Change that cell any time—no code edit or redeploy is needed.</p><div class="settingPath"><span>Settings</span><b>TeacherPassword</b><em>Value = your password</em></div><button id="teacherRefreshBtn" class="btn primary">I updated the Sheet — Refresh</button><div id="teacherMsg" class="formMsg"></div></section>`}
function teacherForm(exams,student={}){const assigned=new Set(student.AssignedCourses||[]),editing=!!student.StudentID;return `<section class="contentCard glass teacherFormCard"><div class="eyebrow">Student account</div><h2>${editing?'Edit student':'Create student'}</h2><input id="studentEditId" type="hidden" value="${esc(student.StudentID||'')}"><label class="formLabel">Student ID ${editing?'(locked)':'(optional)'}</label><input id="studentFormId" class="field" value="${esc(student.StudentID||'')}" placeholder="e.g. STU001" ${editing?'readonly':''}><label class="formLabel">Student name</label><input id="studentFormName" class="field" value="${esc(student.StudentName||'')}" placeholder="Full name"><label class="formLabel">Password ${editing?'(leave blank to keep current)':''}</label><input id="studentFormPassword" class="field" type="password" placeholder="${editing?'New password (optional)':'Password'}"><label class="formLabel">Assigned courses</label><div class="courseChecks">${exams.map(e=>`<label><input type="checkbox" value="${esc(e.ExamID)}" ${assigned.has(e.ExamID)?'checked':''}> <span>${esc(e.ExamName)}</span></label>`).join('')}</div><label class="toggleLabel"><input id="studentFormActive" type="checkbox" ${student.Active!==false?'checked':''}> Active</label><div class="formActions"><button id="saveStudentBtn" class="btn primary">${editing?'Update Student':'Create Student'}</button><button id="cancelStudentBtn" class="btn">Clear</button></div><div id="studentFormMsg" class="formMsg"></div></section>`}
function teacherList(students){return `<section class="contentCard glass"><div class="sectionHead"><div><div class="eyebrow">Students</div><h2>${students.length} account${students.length===1?'':'s'}</h2></div></div>${students.length?`<div class="teacherStudentList">${students.map(s=>`<div class="teacherStudentRow"><div><b>${esc(s.StudentName)}</b><span>${esc(s.StudentID)} • ${(s.AssignedCourses||[]).length} course${(s.AssignedCourses||[]).length===1?'':'s'} • ${s.Active?'Active':'Inactive'}</span></div><div class="rowActions"><button class="btn editStudent" data-id="${esc(s.StudentID)}">Edit</button><button class="btn danger deleteStudent" data-id="${esc(s.StudentID)}">Delete</button></div></div>`).join('')}</div>`:'<div class="empty">No students yet. Create the first student using the form.</div>'}</section>`}
async function initTeacher(){document.body.insertAdjacentHTML('afterbegin',nav());document.body.insertAdjacentHTML('beforeend',footer());refreshThemeButtons();setBackendBadge();const root=$('teacherRoot');try{const status=await jsonp('teacherstatus');if(!status.configured){root.innerHTML=teacherSetupCard();$('teacherRefreshBtn').onclick=()=>location.reload();return}if(!teacherToken()){root.innerHTML=teacherLoginCard();$('teacherLoginBtn').onclick=async()=>{const pw=$('teacherPassword').value,msg=$('teacherMsg');if(!pw){msg.textContent='Enter the teacher password.';return}$('teacherLoginBtn').disabled=true;try{const hash=await sha256(pw),d=await jsonp('teacherLogin',{passwordHash:hash});if(!d.ok)throw Error(d.error||'Login failed');setTeacherToken(d.token);await renderTeacher()}catch(e){msg.textContent=e.message}finally{$('teacherLoginBtn').disabled=false}};return}await renderTeacher()}catch(e){root.innerHTML=`<div class="errorCard glass"><b>Teacher backend error</b><span>${esc(e.message)}</span><a class="btn" href="diagnostics.html">Run diagnostics</a></div>`}}
async function renderTeacher(){const root=$('teacherRoot');root.innerHTML='<div class="loadingCard glass">Loading teacher workspace…</div>';try{const d=await jsonp('teacherstudents',{token:teacherToken()});if(!d.ok)throw Error(d.error||'Could not load students');const exams=d.exams||[],students=d.students||[];root.innerHTML=`<div class="teacherGrid"><div id="teacherFormHost">${teacherForm(exams)}</div><div id="teacherListHost">${teacherList(students)}</div></div>`;wireTeacher(exams,students)}catch(e){if(/session|login/i.test(e.message||'')){setTeacherToken('');location.reload();return}root.innerHTML=`<div class="errorCard glass"><b>Could not load students</b><span>${esc(e.message)}</span></div>`}}
async function wireTeacher(exams,students){const renderForm=student=>{$('teacherFormHost').innerHTML=teacherForm(exams,student||{});wireForm()};const wireForm=()=>{$('cancelStudentBtn').onclick=()=>renderForm({});$('saveStudentBtn').onclick=async()=>{const msg=$('studentFormMsg'),id=$('studentFormId').value.trim(),name=$('studentFormName').value.trim(),pw=$('studentFormPassword').value,courses=qs('#teacherFormHost input[type=checkbox]:checked').map(x=>x.value),active=$('studentFormActive').checked,editing=$('studentEditId').value.trim();if(!name){msg.textContent='Student name is required.';return}if(!editing&&id&&students.some(s=>s.StudentID===id)){msg.textContent='Student ID already exists.';return}if(!editing&&!pw){msg.textContent='Enter a password for the new student.';return}$('saveStudentBtn').disabled=true;msg.textContent='Saving…';try{const passwordHash=pw?await sha256(pw):'',d=await jsonp('teacherSaveStudent',{token:teacherToken(),studentId:id,originalStudentId:editing,studentName:name,passwordHash,assignedCourses:courses.join(','),active:String(active)});if(!d.ok)throw Error(d.error||'Could not save');const idx=students.findIndex(s=>s.StudentID===d.student.StudentID);if(idx>=0)students[idx]=d.student;else students.push(d.student);renderForm({});$('teacherListHost').innerHTML=teacherList(students);wireList()}catch(e){msg.textContent=e.message}finally{$('saveStudentBtn').disabled=false}}};const wireList=()=>{qs('.editStudent').forEach(b=>b.onclick=()=>{const s=students.find(x=>x.StudentID===b.dataset.id);renderForm(s||{})});qs('.deleteStudent').forEach(b=>b.onclick=async()=>{const s=students.find(x=>x.StudentID===b.dataset.id);if(!s||!confirm(`Delete ${s.StudentName}? Their saved progress and notes will also be removed.`))return;try{const d=await jsonp('teacherDeleteStudent',{token:teacherToken(),studentId:s.StudentID});if(!d.ok)throw Error(d.error||'Could not delete');const i=students.findIndex(x=>x.StudentID===s.StudentID);if(i>=0)students.splice(i,1);$('teacherListHost').innerHTML=teacherList(students);wireList()}catch(e){alert(e.message||'Could not delete')}})};wireForm();wireList()}
async function initDiagnostics(){const el=$('diag');if(!el)return;if(!apiReady()){el.innerHTML='<b>Backend:</b> Not configured. Add the deployed /exec URL to config.js.';return}try{const d=await rawJsonp('health'),p=d.counts||{},available=d.availableExamIds||[],expected=String(C.MASTER_SPREADSHEET_ID||''),actual=String(d.masterSpreadsheetId||d.spreadsheetId||''),verified=!!expected&&actual===expected&&d.readWriteUnified!==false;el.innerHTML=`<div class="diagGrid"><div><span>Backend</span><b>${d.ok?'Connected':'Error'}</b></div><div><span>Version</span><b>${esc(d.backendVersion||d.version||'unknown')}</b></div><div><span>Master target</span><b>${verified?'Verified':'Mismatch'}</b></div><div><span>Sheet exam rows</span><b>${p.exams||0}</b></div><div><span>Public exams</span><b>${p.publicExams??available.length}</b></div><div><span>Syllabus rows</span><b>${p.syllabus||0}</b></div></div><p class="mutedText"><b>Expected Sheet ID:</b> ${esc(expected||'Not configured')}</p><p class="mutedText"><b>Backend Sheet ID:</b> ${esc(actual||'Not reported')}</p><p class="mutedText"><b>Read target:</b> ${esc(d.readSpreadsheetId||actual||'Not reported')}<br><b>Write target:</b> ${esc(d.writeSpreadsheetId||actual||'Not reported')}</p><p class="mutedText"><b>Backend public ExamIDs:</b> ${esc(available.join(', ')||'None')}</p>${!verified?`<p class="diagWarn"><b>Deployment mismatch:</b> this /exec URL is not verified against the configured master Sheet. Student/teacher requests are intentionally blocked until Code.gs is redeployed.</p>`:''}<p class="mutedText">Missing sheets: ${esc((d.missingSheets||[]).join(', ')||'None')}</p>`}catch(e){el.innerHTML=`<b>Backend error:</b> ${esc(e.message)}<p>Deploy the latest Code.gs as a new Web App version and confirm config.js points to that /exec URL.</p>`}}
